import java.util.*;

public class D {
    public static void main(String[] args) {
        Scanner in = new Scanner(System.in);
        long n = in.nextLong();
        long m = in.nextLong();
        System.out.println(compute(n, m));
    }

    static long compute(long a, long b) {
        if (b < a) {
            long tmp = a;
            a = b;
            b = tmp;
        }
        if (a == 1) return pattern1(b);
        if (a == 2) {
            if (b < 3) return 0;
            if (b == 3) return 4;
            if (b == 7) return 12;
            return 2 * b;
        }
        return 2 * (a * b / 2);
    }

    static long pattern1(long m) {
        long base = 6 * (m / 6);
        long r = m % 6;
        if (r == 5) return base + 4;
        if (r == 4) return base + 2;
        return base;
    }
}
